"""Prepare manufacturer referenced or explicitly bounded teaching footprints."""
import pathlib,json
ROOT=pathlib.Path(__file__).resolve().parents[1];BASE=ROOT/'examples/de_15_26_20261019';LIB=BASE/'library'
specs=[{'name':'de_abm3b_5032','body':[5.0,3.2],'height':1.1,'pins':[['1',-2,-1.2,'de_smd180x120'],['2',2,-1.2,'de_smd180x120'],['3',2,1.2,'de_smd180x120'],['4',-2,1.2,'de_smd180x120']],'source':'Abracon ABM3B Rev U 2024-08-27 p3 TOP VIEW circuit/land. 1&3 resonator; 2&4 GND. Source: learning/sources/de_15_26_20261019/ABM3B.pdf','bound':[3.2,2.05]},
{'name':'de_capradial_6d3_p2d5','body':[6.3,6.3],'height':11,'pins':[['1',-1.25,0,'VIA_1D0_1D54S'],['2',1.25,0,'VIA_1D0_1D54']],'source':'Teaching procurement envelope only. No MPN selected, not manufacturing released. 6.3 mm max body / 2.5 mm nominal lead pitch / 11 mm max height; pin1 positive. Hole 1.0 mm borrowed from verified isolated header pad, real lead/hole fit pending.','bound':[3.5,3.5]},
{'name':'de_xal6060_2land','body':[6.56,6.76],'height':6.1,'pins':[['1',2.02,0,'de_smd143x550'],['2',-2.02,0,'de_smd143x550']],'source':'Coilcraft Document 887-4 revised 2026-02-25 p4. XAL6060-153MEC. Body nominal 6.36(+/-.2)x6.56(+/-.2)mm, assembly uses max. 2x 1.43x5.50mm lands, center pitch 4.04mm. TOP VIEW short lead marking right: local pin1 right=BUCK_SW, pin2 left=V5. Manufacturer does not assign electrical polarity; local numbering records EMI placement intention.','bound':[3.55,3.65]}]
pads={'de_smd180x120':[1.8,1.2],'de_smd143x550':[1.43,5.5]}
for name,(w,h) in pads.items():
    xml='<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE padstack>\n<padstack version="1.0"><padstackname>'+name+'</padstackname><padstackusage>SMD_PIN</padstackusage><units>Mm</units><accuracy>3</accuracy><drillinfo><slothole><holetype>NONE</holetype></slothole></drillinfo>'
    for layer,ww,hh in [('BEGIN_LAYER',w,h),('TOP_SOLDER_MASK_PAD',w+.1,h+.1),('TOP_PASTE_MASK_PAD',w,h)]:xml+=f'<pad><type>REGULAR_PAD</type><layer>{layer}</layer><figure>RECTANGLE</figure><offset>(0;0)</offset><width>{ww:.3f}</width><height>{hh:.3f}</height></pad>'
    (LIB/(name+'.pxml')).write_text(xml+'</padstack>\n',encoding='ascii')
for s in specs:
    name=s['name'];log=ROOT/'staging/de_15_26_20261019'/('create_'+name);log.mkdir(exist_ok=True)
    lines=['procedure(deCustomCreate()','let((pad result style bound f)','unless(equal(axlDesignType(t) "PACKAGE") error("Not a package\\n"))','unless(length(axlDBGetDesign()->pins)==0 error("Not empty\\n"))','axlDBChangeDesignUnits("millimeters" 3)','axlDBChangeDesignExtents(list(-15:-15 15:15))',f'axlSetVariable("psmpath" list("{LIB.as_posix()}"))',f'axlSetVariable("padpath" list("{LIB.as_posix()}"))','style=make_axlTextOrientation(?textBlock "1" ?rotation 0 ?mirrored nil ?justify "center")']
    for num,x,y,pad in s['pins']:lines += [f'pad=axlLoadPadstack("{pad}")','unless(pad error("Cannot load pad\\n"))',f'result=axlDBCreatePin(pad {x}:{y} make_axlPinText(?number "{num}" ?offset 0:0 ?text style) 0.0)','unless(result error("Cannot create pin\\n"))']
    bx,by=[v/2 for v in s['body']];ex,ey=s['bound']
    lines += [f'unless(axlDBCreateLine(list({-bx}:{-by} {bx}:{-by} {bx}:{by} {-bx}:{by} {-bx}:{-by}) 0.05 "PACKAGE GEOMETRY/ASSEMBLY_TOP" nil nil) error("Assembly failed\\n"))',f'result=axlDBCreateRectangle(list({-ex}:{-ey} {ex}:{ey}) t "PACKAGE GEOMETRY/PLACE_BOUND_TOP" nil nil)','unless(result error("Bound failed\\n"))','bound=car(result)',f'unless(axlDBAddProp(list(bound) list("PACKAGE_HEIGHT_MAX" "{s["height"]} MM")) error("Height failed\\n"))']
    if name=='de_abm3b_5032':lines += ['unless(axlDBCreateLine(list(-0.8:1.9 0.8:1.9) 0.12 "PACKAGE GEOMETRY/SILKSCREEN_TOP" nil nil) error("Silk failed\\n"))','unless(axlDBCreateLine(list(-0.8:-1.9 0.8:-1.9) 0.12 "PACKAGE GEOMETRY/SILKSCREEN_TOP" nil nil) error("Silk failed\\n"))','unless(axlDBCreateLine(list(-3.1:-1.9 -3.1:-2.1 -2.9:-2.1) 0.12 "PACKAGE GEOMETRY/SILKSCREEN_TOP" nil nil) error("Pin1 marker failed\\n"))']
    elif name=='de_capradial_6d3_p2d5':lines += ['unless(axlDBCreateText("+" -2.7:0 style "PACKAGE GEOMETRY/SILKSCREEN_TOP" nil) error("Plus marker failed\\n"))']
    else:lines += ['unless(axlDBCreateLine(list(3.4:-2.6 3.4:2.6) 0.12 "PACKAGE GEOMETRY/SILKSCREEN_TOP" nil nil) error("Short lead marker failed\\n"))']
    lines += ['unless(axlDBCreateText("X*" 0:0 style "REF DES/ASSEMBLY_TOP" nil) error("Refdes failed\\n"))',f'unless(axlSaveDesign(?design "{(LIB/(name+".dra")).as_posix()}" ?noMru t ?noConfirm t) error("Save failed\\n"))',f'unless(axlCompileSymbol(?symbol "{(LIB/name).as_posix()}") error("Compile failed\\n"))',f'f=outfile("{log.as_posix()}/create.txt")',f'fprintf(f "DE_CUSTOM_CREATE_COMPLETE {name}\\n")','close(f)','t))']
    il=ROOT/'scripts'/('de_create_'+name+'.il');il.write_text('\n'.join(lines)+'\n',encoding='ascii')
    scr=il.with_suffix('.scr');scr.write_text('set NOCONFIRM\nskill errset(load("'+il.as_posix()+'") t)\nskill errset(deCustomCreate() t)\nquit\nfillin "yes"\n',encoding='ascii')
(BASE/'custom_package_specs.json').write_text(json.dumps({'packages':specs,'pads':pads,'maskExpansionPerSide':.05,'paste':'1:1 copper for teaching; assembly review required'},indent=2),encoding='utf-8')
print('Prepared',len(specs),'native packages and',len(pads),'native padstack input')
